def count_triangles(edges, n):
    edge_set = {(min(a, b), max(a, b)) for a, b in edges}
    triangles = 0
    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            if (u, v) in edge_set:
                for w in range(v + 1, n + 1):
                    if (u, w) in edge_set and (v, w) in edge_set:
                        triangles += 1
    return triangles

